namespace ProformaViewer.Services;
public static class PageSpecParser { public static IReadOnlyList<int> Parse(string value){if(string.IsNullOrWhiteSpace(value))throw new FormatException("Page is blank.");var pages=new List<int>();foreach(var raw in value.Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)){var token=raw.Trim();var x=token.IndexOf('x',StringComparison.OrdinalIgnoreCase);if(x>0){var page=P(token[..x]);var count=P(token[(x+1)..]);for(var i=0;i<count;i++)pages.Add(page);}else pages.Add(P(token));}return pages.Count>0?pages:throw new FormatException($"Invalid page value '{value}'.");}static int P(string s)=>int.TryParse(s.Trim(),out var n)&&n>0?n:throw new FormatException($"Invalid page number '{s}'."); }
